// Pure deterministic helper to calculate polar coordinates for layout elements
const polarToCartesian = (centerX: number, centerY: number, radius: number, angleInDegrees: number) => {
  const angleInRadians = (angleInDegrees - 90) * Math.PI / 180.0;
  return {
    x: centerX + radius * Math.cos(angleInRadians),
    y: centerY + radius * Math.sin(angleInRadians),
  };
};

// Generates correct SVG paths for circular segments/arcs
const describeArc = (x: number, y: number, radius: number, startAngle: number, endAngle: number) => {
  const start = polarToCartesian(x, y, radius, endAngle);
  const end = polarToCartesian(x, y, radius, startAngle);
  const largeArcFlag = endAngle - startAngle <= 180 ? "0" : "1";
  return [
    "M", start.x, start.y,
    "A", radius, radius, 0, largeArcFlag, 0, end.x, end.y
  ].join(" ");
};

// Main Zod Schema definition


export type WheelOfAwarenessProps = Record<string, any>;

const WheelOfAwareness: React.FC<WheelOfAwarenessProps> = ({
  backgroundColor = "#03070d",
  transparentBackground = false,
  durationInSeconds = 15,
  wheelScale = 1.0,
  glowColor = "#00e5ff",
  highlightDuration = 55,
  showOuterTracks = true,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Dynamic layout measurements based on full viewport dimensions
  const baseWheelSize = height * 0.76;
  const wheelSize = baseWheelSize * wheelScale;
  const wheelRadius = wheelSize / 2;
  const hubSize = wheelSize * 0.35;
  const hubRadius = hubSize / 2;

  const centerX = width / 2;
  const centerY = height / 2;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Background glow spots movement logic
  const bgGlows = [
    { x: 0.2, y: 0.3, size: height * 0.5, color: "rgba(19, 168, 179, 0.14)", speed: 0.02 },
    { x: 0.8, y: 0.2, size: height * 0.6, color: "rgba(133, 196, 65, 0.09)", speed: 0.015 },
    { x: 0.7, y: 0.8, size: height * 0.55, color: "rgba(242, 122, 24, 0.09)", speed: 0.025 },
    { x: 0.3, y: 0.7, size: height * 0.6, color: "rgba(114, 78, 155, 0.12)", speed: 0.018 },
  ];

  // Outer track variables
  const trackRadius = wheelRadius + 28;
  const trackSize = (trackRadius + 30) * 2;

  // Global entrance timing calculations
  const introDuration = 45; 
  const hubStartFrame = 35;

  // Calculate activation level of a specific wedge index for highlighting sequence
  const getWedgeActivation = (i: number, currentFrame: number) => {
    if (currentFrame < introDuration + 15) return 0;
    const startOffset = introDuration + 15;
    const cycleLength = highlightDuration * 8;
    const cycleFrame = (currentFrame - startOffset) % cycleLength;
    const activeIndex = Math.floor(cycleFrame / highlightDuration);
    const offset = cycleFrame % highlightDuration;

    if (i === activeIndex) {
      return interpolate(offset, [0, 8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    }
    if (i === (activeIndex - 1 + 8) % 8) {
      return interpolate(offset, [0, 8], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    }
    return 0;
  };

  // Outer track animation
  const outerRotation = (frame * 0.4) % 360;
  const beadAngle = 180 + Math.sin(frame * 0.04) * 60;
  const beadPos = polarToCartesian(centerX, centerY, trackRadius, beadAngle);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Dynamic Background Atmosphere */}
      {!transparentBackground && bgGlows.map((glow, idx) => {
        const dynamicX = glow.x * width + Math.sin(frame * glow.speed) * 45;
        const dynamicY = glow.y * height + Math.cos(frame * glow.speed) * 45;
        return (
          <div
            key={idx}
            style={{
              position: "absolute",
              left: dynamicX - glow.size / 2,
              top: dynamicY - glow.size / 2,
              width: glow.size,
              height: glow.size,
              backgroundColor: glow.color,
              borderRadius: "50%",
              filter: "blur(90px)",
              pointerEvents: "none",
              transition: "none",
            }}
          />
        );
      })}

      {/* Outer Glowing Tracks & Arrows */}
      {showOuterTracks && (
        <div
          style={{
            position: "absolute",
            left: centerX - trackSize / 2,
            top: centerY - trackSize / 2,
            width: trackSize,
            height: trackSize,
            pointerEvents: "none",
            transform: `rotate(${outerRotation}deg)`,
            transformOrigin: "center center",
            transition: "none",
          }}
        >
          <svg width={trackSize} height={trackSize} style={{ overflow: "visible", transition: "none" }}>
            <defs>
              <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
                <feGaussianBlur stdDeviation="6" result="blur" />
                <feComposite in="SourceGraphic" in2="blur" operator="over" />
              </filter>
            </defs>
            {/* Background thin guide ring */}
            <circle
              cx={trackSize / 2}
              cy={trackSize / 2}
              r={trackRadius}
              stroke={glowColor}
              strokeWidth={1}
              strokeDasharray="4 8"
              fill="none"
              opacity={0.3}
            />
            {/* Glowing active arc */}
            <path
              d={describeArc(trackSize / 2, trackSize / 2, trackRadius, -60, 160)}
              stroke={glowColor}
              strokeWidth={3}
              fill="none"
              strokeLinecap="round"
              filter="url(#glow)"
              opacity={0.8}
            />
            {/* Clockwise Arrowhead at the end of the arc */}
            {(() => {
              const headAngle = 160;
              const p = polarToCartesian(trackSize / 2, trackSize / 2, trackRadius, headAngle);
              return (
                <g transform={`translate(${p.x}, ${p.y}) rotate(${headAngle + 90})`} style={{ transition: "none" }}>
                  <path
                    d="M -8,-10 L 0,2 L 8,-10"
                    stroke={glowColor}
                    strokeWidth={3}
                    fill="none"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    filter="url(#glow)"
                  />
                </g>
              );
            })()}
          </svg>
        </div>
      )}

      {/* Back and Forth Sliding Bead Track on the Left */}
      {showOuterTracks && (
        <div style={{ position: "absolute", inset: 0, pointerEvents: "none", transition: "none" }}>
          <div
            style={{
              position: "absolute",
              left: beadPos.x - 7,
              top: beadPos.y - 7,
              width: 14,
              height: 14,
              borderRadius: "50%",
              backgroundColor: "#ffffff",
              boxShadow: `0 0 14px 4px ${glowColor}`,
              border: `2px solid ${glowColor}`,
              transition: "none",
            }}
          />
        </div>
      )}

      {/* Main Interactive Wheel Anchor */}
      <div
        style={{
          position: "absolute",
          left: centerX - wheelRadius,
          top: centerY - wheelRadius,
          width: wheelSize,
          height: wheelSize,
          transition: "none",
        }}
      >
        {/* Render Wedge Segments */}
        {segments.map((seg, i) => {
          // Entry animation spring
          const segmentDelay = i * 4;
          const entryProgress = spring({
            frame: frame - segmentDelay,
            fps,
            config: { damping: 14, mass: 0.9 },
          });

          // Highlight transition value
          const activeVal = getWedgeActivation(i, frame);
          
          // Interpolated values for smooth highlighted state
          const wedgeScale = entryProgress * (1.0 + activeVal * 0.04);
          const shadowBlur = interpolate(activeVal, [0, 1], [4, 25]);
          const shadowOpacity = interpolate(activeVal, [0, 1], [0.15, 0.7]);
          
          // Angle configurations for the pie segments (45 degrees/segment)
          const rotationRad = -Math.PI / 8 + (i * Math.PI) / 4;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                width: wheelSize,
                height: wheelSize,
                transform: `scale(${wedgeScale})`,
                transformOrigin: "center center",
                opacity: entryProgress,
                filter: `drop-shadow(0px 0px ${shadowBlur}px rgba(${idxToRgb(seg.color)}, ${shadowOpacity}))`,
                transition: "none",
              }}
            >
              <Pie
                radius={wheelRadius}
                progress={0.125}
                rotation={rotationRad}
                fill={seg.color}
                stroke="#ffffff"
                strokeWidth={3}
                style={{ position: "absolute", overflow: "visible" }}
              />
            </div>
          );
        })}

        {/* Render Wedge Contents (Text and Icons positioned inside the sectors) */}
        {segments.map((seg, i) => {
          const segmentDelay = i * 4;
          const entryProgress = spring({
            frame: frame - segmentDelay - 8,
            fps,
            config: { damping: 12 },
          });

          const activeVal = getWedgeActivation(i, frame);

          // Placement coordinates calculations using polar conversion
          const angleDeg = i * 45;
          const contentRadius = wheelRadius * 0.65;
          const contentPos = polarToCartesian(wheelRadius, wheelRadius, contentRadius, angleDeg);

          // Motion offset on activation
          const scale = entryProgress * (1.0 + activeVal * 0.05);
          const pulseTranslateY = Math.sin(frame * 0.08) * 3 * activeVal;
          const dimOpacity = interpolate(activeVal, [0, 1], [0.8, 1.0]);

          return (
            <div
              key={`text-${i}`}
              style={{
                position: "absolute",
                left: contentPos.x,
                top: contentPos.y,
                width: height * 0.18,
                transform: `translate(-50%, -50%) scale(${scale}) translateY(${pulseTranslateY}px)`,
                transformOrigin: "center center",
                opacity: entryProgress * dimOpacity,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                textAlign: "center",
                color: "#ffffff",
                pointerEvents: "none",
                transition: "none",
              }}
            >
              {/* Wedge Title */}
              <div
                style={{
                  fontFamily: montserratFamily,
                  fontWeight: 700,
                  fontSize: Math.max(11, height * 0.019),
                  textShadow: "0px 2px 6px rgba(0, 0, 0, 0.6)",
                  lineHeight: 1.1,
                  marginBottom: height * 0.005,
                  letterSpacing: "0.2px",
                  transition: "none",
                }}
              >
                {seg.title}
              </div>

              {/* Wedge Description */}
              <div
                style={{
                  fontFamily: interFamily,
                  fontWeight: 500,
                  fontSize: Math.max(9, height * 0.0125),
                  opacity: interpolate(activeVal, [0, 1], [0.85, 1]),
                  textShadow: "0px 1px 4px rgba(0, 0, 0, 0.7)",
                  lineHeight: 1.25,
                  marginBottom: height * 0.01,
                  whiteSpace: "pre-line",
                  transition: "none",
                }}
              >
                {seg.desc}
              </div>

              {/* Wedge Icon Container */}
              <div
                style={{
                  transform: `scale(${1 + activeVal * 0.1})`,
                  filter: `drop-shadow(0px 2px 4px rgba(0,0,0,0.4))`,
                  transition: "none",
                }}
              >
                <WedgeIcon type={seg.icon} color="#ffffff" size={Math.max(20, height * 0.03)} />
              </div>
            </div>
          );
        })}

        {/* Central White Hub "Wheel of Awareness" */}
        {(() => {
          const hubEntrance = spring({
            frame: frame - hubStartFrame,
            fps,
            config: { damping: 11, mass: 0.8 },
          });

          return (
            <div
              style={{
                position: "absolute",
                left: wheelRadius - hubRadius,
                top: wheelRadius - hubRadius,
                width: hubSize,
                height: hubSize,
                borderRadius: "50%",
                backgroundColor: "#ffffff",
                boxShadow: "0px 10px 35px rgba(0, 0, 0, 0.45), inset 0px 0px 12px rgba(0,0,0,0.05)",
                display: "flex",
                flexDirection: "column",
                justifyContent: "center",
                alignItems: "center",
                transform: `scale(${hubEntrance})`,
                transformOrigin: "center center",
                zIndex: 10,
                border: "2px solid rgba(255, 255, 255, 0.9)",
                padding: height * 0.02,
                boxSizing: "border-box",
                transition: "none",
              }}
            >
              <div
                style={{
                  fontFamily: montserratFamily,
                  fontWeight: 800,
                  color: "#050a12",
                  fontSize: Math.max(14, height * 0.031),
                  lineHeight: 1.05,
                  textAlign: "center",
                  textTransform: "capitalize",
                  letterSpacing: "-0.5px",
                  transition: "none",
                }}
              >
                Wheel
              </div>
              <div
                style={{
                  fontFamily: interFamily,
                  fontWeight: 400,
                  color: "#1e293b",
                  fontSize: Math.max(11, height * 0.019),
                  margin: `${height * 0.002}px 0`,
                  fontStyle: "italic",
                  transition: "none",
                }}
              >
                of
              </div>
              <div
                style={{
                  fontFamily: montserratFamily,
                  fontWeight: 800,
                  color: "#050a12",
                  fontSize: Math.max(14, height * 0.031),
                  lineHeight: 1.05,
                  textAlign: "center",
                  letterSpacing: "-0.5px",
                  transition: "none",
                }}
              >
                Awareness
              </div>
            </div>
          );
        })()}
      </div>
    </AbsoluteFill>
  );
};

// Helper utility to extract raw RGB values from Hex color for drop shadows
const idxToRgb = (hex: string): string => {
  const cleanHex = hex.replace("#", "");
  const r = parseInt(cleanHex.substring(0, 2), 16);
  const g = parseInt(cleanHex.substring(2, 4), 16);
  const b = parseInt(cleanHex.substring(4, 6), 16);
  return `${r}, ${g}, ${b}`;
};

export default WheelOfAwareness;